package common

import chisel3._
import chisel3.util._

object SvGenerationUtils {
  def GenerateInterface(io: RawBundle, prefix: String): String = {
    val fields = io.getElements.toList
    val lines = fields.flatMap {
      case (name, data) =>
        GenerateInterfaceField(prefix + "_" + name, data)
    }
    lines.mkString("\n")
  }

  private def GenerateInterfaceField(name: String, data: Data): Seq[String] = {
    data match {
      case bundle: RawBundle =>
        bundle.getElements.toList.flatMap {
          case (fieldName, fieldData) =>
            GenerateInterfaceField(name + "_" + fieldName, fieldData)
        }
      case vec: Vec[_] =>
        (0 until vec.length).flatMap { i =>
          GenerateInterfaceField(s"${name}_${i}", vec(i))
        }
      case clock: Clock =>
        Seq(s"  input  logic $name")
      case asyncreset: AsyncReset =>
        Seq(s"  input  logic $name")
      case reset: Reset =>
        Seq(s"  input  logic $name")
      case u: UInt =>
        val dir = if (u.isInput) "input" else "output"
        if (u.getWidth == 1) {
          Seq(f"  $dir%-6s logic $name")
        } else {
          Seq(f"  $dir%-6s logic [${u.getWidth - 1}:0] $name")
        }
      case s: SInt =>
        val dir = if (s.isInput) "input" else "output"
        if (s.getWidth == 1) {
          Seq(f"  $dir%-6s logic $name")
        } else {
          Seq(f"  $dir%-6s logic [${s.getWidth - 1}:0] $name")
        }
      case other =>
        Seq(s"  // unknown: $other")
    }
  }
}

