package common

import chisel3._
import chisel3.util._

object Library {

  /** Force the bits of a Valid bundle to zero when invalid. */
  def ForceZero[T <: Data](in: Valid[T]): Valid[T] = {
    val out = Wire(Valid(in.bits.cloneType))
    out.valid := in.valid
    out.bits := Mux(in.valid, in.bits, 0.U.asTypeOf(in.bits))
    out
  }

  /** Interleave elements of two 32-bit values at byte/half/word granularity.
    *
    * @param sz size selector: 4=words(32 bits each), 2=halves(16 bits each), 1=bytes(8 bits each)
    * @param a  first 32-bit operand
    * @param b  second 32-bit operand
    * @return 64-bit interleaved result
    */
  def Zip32(sz: UInt, a: UInt, b: UInt): UInt = {
    val aLo = a(7, 0)
    val aHi = a(15, 8)
    val bLo = b(7, 0)
    val bHi = b(15, 8)

    // For 16-bit halves within each 32-bit word
    val a0 = a(15, 0)
    val a1 = a(31, 16)
    val b0 = b(15, 0)
    val b1 = b(31, 16)

    sz match {
      case _ =>
        Mux(sz === 4.U,
          // Word-level: b:32, a:32
          Cat(b, a),
          Mux(sz === 2.U,
            // Half-level: interleave 16-bit halves
            Cat(b(31, 16), a(31, 16), b(15, 0), a(15, 0)),
            // Byte-level: interleave 8-bit bytes (low 2 bytes used)
            Cat(
              b(31, 24), a(31, 24),
              b(23, 16), a(23, 16),
              b(15, 8), a(15, 8),
              b(7, 0), a(7, 0)
            )
          )
        )
    }
  }

  /** Rotate a vector of Valid elements left by `shift` positions. */
  def RotateVectorLeft[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    for (i <- 0 until n) {
      val src = (i + shift) % n
      out(i) := in(src)
    }
    out
  }

  /** Rotate a vector of Valid elements right by `shift` positions. */
  def RotateVectorRight[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    for (i <- 0 until n) {
      val src = ((i - shift) + n * shift.getWidth.exp2) % n
      out(i) := in(src)
    }
    out
  }

  /** Shift a vector of Valid elements left by `shift` positions, filling overflow with zeros. */
  def ShiftVectorLeft[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    for (i <- 0 until n) {
      val src = i + shift
      val wrapped = src - n
      out(i) := Mux(src < n.U, in(src), Mux(wrapped >= 0.U && wrapped < n.U, in(wrapped), 0.U.asTypeOf(in(0))))

    }
    out
  }

  /** Shift a vector of Valid elements right by `shift` positions, filling underflow with zeros. */
  def ShiftVectorRight[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    for (i <- 0 until n) {
      val src = i - shift
      out(i) := Mux(src >= 0.S, in((src + (n * 4).U).asUInt % n.U), 0.U.asTypeOf(in(0)))
    }
    out
  }
}

