package common

import chisel3._
import chisel3.util._

object Library {

  /** Force the bits of a Valid bundle to zero when invalid. */
  def ForceZero[T <: Data](in: Valid[T]): Valid[T] = {
    val out = Wire(Valid(chiselTypeOf(in.bits)))
    out.valid := in.valid
    out.bits := Mux(in.valid, in.bits, 0.U.asTypeOf(chiselTypeOf(in.bits)))
    out
  }

  /** Interleave elements of two 32-bit values at byte/half/word granularity. */
  def Zip32(sz: UInt, a: UInt, b: UInt): UInt = {
    Mux(sz === 4.U,
      // Word-level: upper 32 bits of 'b', lower 32 bits of 'a'
      Cat(b, a),
      Mux(sz === 2.U,
        // Half-level: interleave 16-bit halves: b1, a1, b0, a0
        Cat(b(31, 16), a(31, 16), b(15, 0), a(15, 0)),
        // Byte-level: interleave 8-bit bytes
        Cat(
          b(31, 24), a(31, 24),
          b(23, 16), a(23, 16),
          b(15, 8),  a(15, 8),
          b(7, 0),   a(7, 0)
        )
      )
    )
  }

  /** Rotate a vector of elements left by `shift` positions. */
  def RotateVectorLeft[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    require(n.isPowerOf2)
    val out = Wire(Vec(n, in(0).cloneType))
    // output[i] = input[(i + shift) % n]
    for (i <- 0 until n) {
      val src = (i.U + shift)(log2Ceil(n) - 1, 0)
      out(i) := in(src)
    }
    out
  }

  /** Rotate a vector of elements right by `shift` positions. */
  def RotateVectorRight[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    require(n.isPowerOf2)
    val out = Wire(Vec(n, in(0).cloneType))
    // output[i] = input[(i - shift + n) % n]
    for (i <- 0 until n) {
      val src = (i.U + n.U - shift)(log2Ceil(n) - 1, 0)
      out(i) := in(src)
    }
    out
  }

  /** Shift a vector of elements left by `shift` positions (towards higher indices).
    * Elements that would overflow (i >= n - shift) are zeroed.
    * output[i] = input[i - shift] when i >= shift, else 0.
    */
  def ShiftVectorLeft[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    // Initialize all outputs to zero
    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(in(0))
    }
    // Route each input to its shifted position
    for (i <- 0 until n) {
      val dst = i.U + shift
      val inBounds = dst < n.U
      when (inBounds) {
        out(dst) := in(i)
      }
    }
    out
  }

  /** Shift a vector of elements right by `shift` positions (towards lower indices).
    * Elements that would underflow (i < shift) are zeroed.
    * output[i] = input[i + shift] when i + shift < n, else 0.
    */
  def ShiftVectorRight[T <: Data](in: Vec[T], shift: UInt): Vec[T] = {
    val n = in.length
    val out = Wire(Vec(n, in(0).cloneType))
    for (i <- 0 until n) {
      out(i) := 0.U.asTypeOf(in(0))
    }
    // Route each input to its shifted position
    for (i <- 0 until n) {
      val dst = i.U - shift
      val inBounds = i.U >= shift
      when (inBounds) {
        out(dst) := in(i)
      }
    }
    out
  }
}

