/** Index allocator using a shifting bitmap. */
class IndexAllocatorShifting(capacity: Int) extends Module {
  val logCap = log2Ceil(capacity)
  val io = IO(new Bundle {
    val alloc = Output(Valid(UInt(logCap.W)))
    val free = Input(Decoupled(UInt(logCap.W)))
  })

  // Bitmap: 1 = free, 0 = occupied, initially all free
  val bitmap = RegInit((BigInt(1) << capacity) - 1).asUInt(capacity.W)

  // Output the first free index (lowest-set bit)
  val freeMask = bitmap
  io.alloc.valid := freeMask.orR
  io.alloc.bits := PriorityEncoder(freeMask)

  // Free port: only accept frees when not allocating
  io.free.ready := !io.alloc.valid

  // Update bitmap on allocation
  when (io.alloc.valid) {
    bitmap := bitmap & ~(1.U << io.alloc.bits)
  }

  // Update bitmap on free
  when (io.free.valid && io.free.ready) {
    bitmap := bitmap | (1.U << io.free.bits)
  }
}

