package common

import chisel3._
import chisel3.util._

/** Index allocator using a bitmap. */
class IndexAllocatorShifting(capacity: Int) extends Module {
  val logCap = log2Ceil(capacity)
  val io = IO(new Bundle {
    val alloc = Output(Valid(UInt(logCap.W)))
    val free = Input(Decoupled(UInt(logCap.W)))
  })

  // Bitmap: 1 = free, 0 = occupied
  val bitmap = RegInit(((BigInt(1) << capacity) - 1).U(capacity.W))

  val freeMask = bitmap
  io.alloc.valid := freeMask.orR
  io.alloc.bits := PriorityEncoder(freeMask)

  val allocFire = io.alloc.valid && io.alloc.ready
  io.free.ready := allocFire && io.free.valid

  when (allocFire) {
    // Mark allocated slot as occupied
    when (io.free.valid && io.free.ready) {
      // Free on same cycle: clear old alloc bit, set freed bit
      bitmap := (bitmap & ~(1.U << io.alloc.bits)) | (1.U << io.free.bits)
    }.otherwise {
      bitmap := bitmap & ~(1.U << io.alloc.bits)
    }
  }

  when (io.free.valid && io.free.ready && !allocFire) {
    bitmap := bitmap | (1.U << io.free.bits)
  }
}

