package common

import chisel3._
import chisel3.util._

/** Multi-element circular buffer with enq/deq up to n elements per cycle. */
class CircularBufferMulti[T <: Data](gen: T, n: Int, capacity: Int) extends Module {
  require(capacity.isPowerOf2)
  require(n <= capacity)

  val io = IO(new Bundle {
    val enqValid = Input(UInt(log2Ceil(n + 1).W))
    val enqData = Input(Vec(n, gen))
    val deqReady = Input(UInt(log2Ceil(n + 1).W))
    val flush = Input(Bool())
    val nEnqueued = Output(UInt(log2Ceil(capacity + 1).W))
    val dataOut = Output(Vec(n, gen))
  })

  val mem = SyncReadMem(capacity, gen)
  val head = RegInit(0.U(log2Ceil(capacity + 1).W))
  val tail = RegInit(0.U(log2Ceil(capacity + 1).W))
  val count = RegInit(0.U(log2Ceil(capacity + 1).W))

  io.nEnqueued := count

  // Enqueue
  when (io.enqValid > 0.U) {
    for (i <- 0 until n) {
      when (i.U < io.enqValid) {
        mem.write(head, io.enqData(i))
        head := head + 1.U
        when (head === capacity.U) { head := 0.U }
      }
    }
    count := count + io.enqValid
  }

  // Dequeue
  when (io.deqReady > 0.U) {
    count := count - io.deqReady
    tail := tail + io.deqReady
    when (tail >= capacity.U) { tail := tail - capacity.U }
  }

  // Flush
  when (io.flush) {
    head := 0.U
    tail := 0.U
    count := 0.U
  }

  // Read output data
  for (i <- 0 until n) {
    val readIdx = (tail + i.U)
    val maskedIdx = Mux(readIdx >= capacity.U, readIdx - capacity.U, readIdx)
    io.dataOut(i) := mem.read(maskedIdx)
  }
}

