package common

import chisel3._
import chisel3.util._

/** FIFO state for multi-element circular buffer. */
object FIFOState {
  def init[T <: Data](capacity: Int, gen: T): FIFOState = {
    require(capacity > 0)
    new FIFOState(capacity, gen)
  }
}

class FIFOState(capacity: Int, genType: Data) {
  private val logSz = if (capacity.isPowerOf2) log2Ceil(capacity) else log2Ceil(capacity + 1)

  val mem = SyncReadMem(capacity, genType.cloneType)
  val head = RegInit(0.U(logSz.W))
  val tail = RegInit(0.U(logSz.W))
  val count = RegInit(0.U(logSz.W))

  def enqueue(dataIn: Vec[Data], n: UInt): FIFOState = {
    when (n > 0.U) {
      for (i <- 0 until dataIn.length) {
        when (i.U < n) {
          mem.write(head, dataIn(i))
          head := head + 1.U
          if (capacity.isPowerOf2) {
            when (head === capacity.U) { head := 0.U }
          } else {
            when (head >= capacity.U) { head := head - capacity.U }
          }
        }
      }
      count := count + n
    }
    this
  }

  def dequeue(n: UInt): FIFOState = {
    when (n > 0.U) {
      count := count - n
      tail := tail + n
      if (capacity.isPowerOf2) {
        when (tail >= capacity.U) { tail := tail - capacity.U }
      } else {
        when (tail >= capacity.U) { tail := tail - capacity.U }
      }
    }
    this
  }

  def flush(): FIFOState = {
    head := 0.U
    tail := 0.U
    count := 0.U
    this
  }

  def peek(n: Int): Vec[Data] = {
    val result = Wire(Vec(n, genType.cloneType))
    for (i <- 0 until n) {
      val readIdx = tail + i.U
      val maskedIdx = Mux(readIdx >= capacity.U, readIdx - capacity.U, readIdx)
      result(i) := mem.read(maskedIdx)
    }
    result
  }

  def invariant(): Bool = {
    count <= capacity.U && head < (capacity + n).U && tail < (capacity + n).U
  }
}

