package common

import chisel3._
import chisel3.util._

/** Gather and Scatter combinational functions. */
object ScatterGather {

  /** Gather: out[i] = data[indices[i]] */
  def Gather(indices: Vec[UInt], data: Vec[UInt]): Vec[UInt] = {
    val n = indices.length
    val out = Wire(Vec(n, data(0).cloneType))
    for (i <- 0 until n) {
      out(i) := data(indices(i))
    }
    out
  }

  /** Scatter: write data[i] to position indices[i] for valid entries.
    * First writer to each position wins.
    * Returns (outData, writeMask, indicesSelected).
    */
  def Scatter(
    indicesValid: Vec[Bool],
    indices: Vec[UInt],
    data: Vec[UInt]
  ): (Vec[UInt], Vec[Bool], Vec[Bool]) = {
    val n = indices.length
    val dataWidth = data(0).getWidth
    val maxIdx = indices(0).getWidth

    val outData = Wire(Vec(n, UInt(dataWidth.W)))
    val writeMask = Wire(Vec(n, Bool()))
    val indicesSelected = Wire(Vec(n, Bool()))

    // For each output position, find which input will write to it
    for (j <- 0 until n) {
      // Check each input to see if it writes to position j
      val writers = (0 until n).map { i =>
        indicesValid(i) && indices(i) === j.U
      }
      // First writer wins
      val winnerOH = PriorityEncoderOH(writers)
      val winner = PriorityEncoder(writers :+ true.B)
      indicesSelected := WireInit(VecInit(Seq.fill(n)(false.B)))

      when (writer.valid) {
        outData(j) := Mux1H(writers, data)
        writeMask(j) := writers.reduce(_ | _)
      }
    }

    // Simpler: compute for each input whether it's selected
    for (i <- 0 until n) {
      val myIndex = indices(i)
      val earlierWriters = (0 until i).map { k =>
        indicesValid(k) && indices(k) === myIndex
      }
      val hasEarlier = earlierWriters.isEmpty || earlierWriters.reduce(_ | _)
      indicesSelected(i) := indicesValid(i) && !earlierWriters.reduce(_ | _)
    }

    // For each output position, compute which data value goes there
    for (j <- 0 until n) {
      val writersForJ = (0 until n).map { i =>
        indicesValid(i) && indices(i) === j.U
      }
      val winnerOH = VecInit(writersForJ)
      writeMask(j) := writerOH.asUInt.orR

      for (i <- 0 until n) {
        // Determine if position i is the winner for position j
        val earlierForJ = (0 until i).map { k =>
          indicesValid(k) && indices(k) === j.U
        }
        val iWinsJ = indicesValid(i) && indices(i) === j.U && !earlierForJ.reduce(_ | _)
      }
      outData(j) := Mux1H(
        (for (i <- 0 until n) yield {
          val earlierForJ = (0 until i).map { k =>
            indicesValid(k) && indices(k) === j.U
          }
          (indicesValid(i) && indices(i) === j.U && !earlierForJ.reduce(_ | _), data(i))
        }),
        0.U(dataWidth.W)
      )
    }

    (outData, writeMask, indicesSelected)
  }
