/** Gather and Scatter combinational functions. */
object ScatterGather {

  /** Gather: out[i] = data[indices[i]] */
  def Gather(indices: Vec[UInt], data: Vec[UInt]): Vec[UInt] = {
    val n = indices.length
    val out = Wire(Vec(n, data(0).cloneType))
    for (i <- 0 until n) {
      out(i) := data(indices(i))
    }
    out
  }

  /** Scatter: write data[i] to position indices[i] for valid entries.
    * For duplicate indices, the first (lowest index) writer wins.
    * Returns (outData, writeMask, indicesSelected).
    */
  def Scatter(
    indicesValid: Vec[Bool],
    indices: Vec[UInt],
    data: Vec[UInt]
  ): (Vec[UInt], Vec[Bool], Vec[Bool]) = {
    val n = indices.length
    val dataWidth = data(0).getWidth

    val outData = Wire(Vec(n, UInt(dataWidth.W)))
    val writeMask = Wire(Vec(n, Bool()))
    val indicesSelected = Wire(Vec(n, Bool()))

    // For each input, determine if it's the first writer to its target index
    for (i <- 0 until n) {
      val noEarlier = !(0 until i).foldLeft(false.B) { (acc, k) =>
        acc || (indicesValid(k) && indices(k) === indices(i))
      }
      indicesSelected(i) := indicesValid(i) && noEarlier
    }

    // For each output position j, compute data and writeMask
    for (j <- 0 until n) {
      val anyWriter = (0 until n).foldLeft(false.B) { (acc, i) =>
        acc || (indicesValid(i) && indices(i) === j.U)
      }
      writeMask(j) := anyWriter

      // Find the winner data for position j using Mux1H
      val muxPairs = (0 until n).map { i =>
        // Check if input i is the first valid writer to position j
        val isTarget = indicesValid(i) && indices(i) === j.U
        val noEarlierToJ = !(0 until i).foldLeft(false.B) { (acc, k) =>
          acc || (indicesValid(k) && indices(k) === j.U)
        }
        (isTarget && noEarlierToJ, data(i))
      }
      outData(j) := Mux1H(muxPairs)
    }

    (outData, writeMask, indicesSelected)
  }
}

