/** IEEE 754 single-precision floating point representation. */
class Fp32 extends Bundle {
  val sign = Bool()
  val exponent = UInt(8.W)
  val mantissa = UInt(23.W)

  def toWord(): UInt = Cat(sign, exponent, mantissa)

  def isZero(): Bool = exponent === 0.U && mantissa === 0.U
  def isInf(): Bool = exponent === 0xFF.U && mantissa === 0.U
  def isNan(): Bool = exponent === 0xFF.U && mantissa =/= 0.U
}

object Fp32 {
  def fromWord(word: UInt): Fp32 = {
    val fp = Wire(new Fp32)
    fp.sign := word(31)
    fp.exponent := word(30, 23)
    fp.mantissa := word(22, 0)
    fp
  }

  /** Convert an integer (unsigned or signed) to a floating point number. */
  def fromInteger(int: UInt, signed: Bool): Fp32 = {
    val fp = Wire(new Fp32)
    val absInt = Mux(signed && int(31) === 1.U, (-int.asSInt).asUInt, int)
    fp.sign := Mux(signed && int(31) === 1.U, true.B, false.B)

    when (absInt === 0.U) {
      // Zero
      fp.sign := 0.U
      fp.exponent := 0.U
      fp.mantissa := 0.U
    } .otherwise {
      // Find MSB position (for both rounding: shift until top 24 bits)
      val leadingZeros = (32 - PriorityEncoder(absInt | 1.U) - 1).U
      val exp = 127 - leadingZeros

      // We need 24 significant bits (23 mantissa + hidden 1)
      // Shift to get top 24 bits at position 23, then extra bit for rounding
      val shift = Mux(leadingZeros > 2.U, leadingZeros - 2.U, 0.U)
      val expanded = absInt << shift

      val top24 = expanded(31, 8)  // 24 bits: hidden 1 + 23 mantissa
      val gBit = expanded(7)       // guard
      val rBit = expanded(6)       // round
      val sticky = (expanded(5, 0) =/= 0.U)  // sticky (OR of remaining)

      // Rounding: round to nearest, ties to even
      val mantissa = Mux(
        (gBit || rBit || sticky) && (top24(0) === 1.U || gBit || rBit),
        (top24 + 1.U)(23, 1),
        top24(23, 1)
      )

      // Handle mantissa overflow
      when (mantissa === 0.U(23.W)) {
        // Mantissa overflow: increment exponent, mantissa becomes 0
        fp.exponent := exp + 1.U
        fp.mantissa := 0.U
      } .otherwise {
        fp.exponent := exp
        fp.mantissa := mantissa
      }

      // Handle overflow to infinity
      when (fp.exponent >= 255.U) {
        fp.exponent := 255.U
        fp.mantissa := 0.U
      }
    }

    fp
  }
}

