/** FIFO state for multi-element circular buffer.
  * Implemented as a Bundle that can be used as a Reg.
  */
object FIFOState {
  def init[T <: Data](capacity: Int, gen: T): FIFOState = {
    require(capacity > 0)
    val szW = log2Ceil(capacity) + 1
    val nW = if (capacity.isPowerOf2) log2Ceil(capacity) else log2Ceil(capacity + 1)
    new FIFOState(capacity, gen, szW, nW)
  }
}

class FIFOState(val capacity: Int, val genType: Data, val szW: Int, val nW: Int) extends Bundle {
  val mem = SyncReadMem(capacity, genType)
  val head = UInt(szW.W)
  val tail = UInt(szW.W)
  val count = UInt(nW.W)

  def enqueue(dataIn: Vec[Data], n: UInt): FIFOState = {
    val next = Wire(new FIFOState(capacity, genType.cloneType, szW, nW))
    next.count := count + n
    next.tail := tail

    val newHead = head + n
    next.head := Mux(newHead >= capacity.U, newHead - capacity.U, newHead)
    next
  }

  def dequeue(n: UInt): FIFOState = {
    val next = Wire(new FIFOState(capacity, genType.cloneType, szW, nW))
    next.count := count - n
    next.head := head
    val newTail = tail + n
    next.tail := Mux(newTail >= capacity.U, newTail - capacity.U, newTail)
    next
  }

  def flush(): FIFOState = {
    val next = Wire(new FIFOState(capacity, genType.cloneType, szW, nW))
    next.count := 0.U
    next.head := 0.U
    next.tail := 0.U
    next
  }

  def peek(n: Int): Vec[Data] = {
    val result = Wire(Vec(n, genType.cloneType))
    for (i <- 0 until n) {
      val readIdx = tail + i.U
      result(i) := mem.read(Mux(readIdx >= capacity.U, readIdx - capacity.U, readIdx))
    }
    result
  }

  def invariant(): Bool = count <= capacity.U
}
